CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sku TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'Uncategorised', compare_at_cents INTEGER NOT NULL DEFAULT 0, low_stock_threshold INTEGER NOT NULL DEFAULT 5, weight_g INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, subtitle TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', price_cents INTEGER NOT NULL CHECK(price_cents>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), image TEXT NOT NULL DEFAULT '', badge TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, customer_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, postcode TEXT NOT NULL, city TEXT NOT NULL, region TEXT NOT NULL, subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, payment_status TEXT NOT NULL DEFAULT 'pending', fulfillment_status TEXT NOT NULL DEFAULT 'unfulfilled', payment_reference TEXT, tracking_number TEXT, courier TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, paid_at TEXT, cancelled_at TEXT);
CREATE TABLE IF NOT EXISTS order_items (order_id TEXT NOT NULL, product_id INTEGER NOT NULL, name TEXT NOT NULL, price_cents INTEGER NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES ('shipping_west','800'),('shipping_east','1500'),('free_shipping_above','20000'),('store_name','Elixiré');
INSERT INTO products (name,subtitle,description,price_cents,stock,image,badge) SELECT 'Elixiré Black Seed Oil','Everyday botanical wellness','A thoughtfully crafted black seed oil product. Final ingredients and product claims are pending client confirmation.',8900,30,'https://images.unsplash.com/photo-1608571423902-eed4a5ad8108?w=900&q=85','BESTSELLER' WHERE NOT EXISTS(SELECT 1 FROM products);
